'use strict';
const data=JSON.parse(document.getElementById('simulation-data').textContent),catalog=data.catalog,sim=GridSimulator,$=id=>document.getElementById(id),keys=sim.KEYS,names=['근력','기민','근골','내공','오성'];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='murim-grid-lab-config-v1';let current,frame=0,timer=null,lastConfig,dirty=false,downloadUrl;
const options=(entries,value)=>entries.map(([id,name])=>`<option value="${escapeHtml(id)}"${id===value?' selected':''}>${escapeHtml(name)}</option>`).join('');
const weaponOptions=Object.entries(catalog.weapons).map(([id,w])=>[id,w.name]);const skillOptions=[['','비워 두기'],...Object.entries(catalog.arts).map(([id,s])=>[id,s.name])];
const policies=[['attack','강한 공격 우선'],['third_guard','강공 + 3행동마다 방어'],['recover','내기 회복 우선']];
function createEditors(){for(let i=0;i<2;i++){const side=document.createElement('section');side.className='editor-side';side.innerHTML=`<h2>${i===0?'내 캐릭터':'상대 캐릭터'}</h2><div class="field-row"><label>이름<input id="name-${i}" maxlength="20"></label><label>체력<input id="hp-${i}" type="number" min="1" max="100000" step="1"></label></div><div class="field-row stats-row">${keys.map((k,n)=>`<label>${names[n]}<input id="${k}-${i}" type="number" min="0" max="100" step="1"></label>`).join('')}</div><div class="build-summary" id="summary-${i}"></div><div class="field-row"><label>장착 무기<select id="weapon-${i}">${options(weaponOptions,'')}</select></label><label>자동 전투 방침<select id="policy-${i}">${options(policies,'attack')}</select></label></div><div class="skill-grid">${[0,1,2,3].map(n=>`<label>무공 ${n+1}<select id="skill-${i}-${n}">${options(skillOptions,'')}</select></label>`).join('')}</div><div class="field-row position-row"><label>시작 가로<input id="x-${i}" type="number" min="1" max="7" step="1"></label><label>시작 세로<input id="y-${i}" type="number" min="1" max="5" step="1"></label><label>속도 강제값(비우면 기민+10)<input id="override-${i}" type="number" min="1" max="500" step="1" placeholder="자동"></label></div><div class="skill-info" id="info-${i}"></div>`;$('editors').append(side)}}
function readConfig(){return {recovery:$('recovery').value,actors:[0,1].map(i=>({name:$('name-'+i).value.trim()||'무명',max_hp:$('hp-'+i).valueAsNumber,stats:Object.fromEntries(keys.map(k=>[k,$(k+'-'+i).valueAsNumber])),weapon:$('weapon-'+i).value,skills:[0,1,2,3].map(n=>$(`skill-${i}-${n}`).value),pos:[$('x-'+i).valueAsNumber,$('y-'+i).valueAsNumber],policy:$('policy-'+i).value,speed_override:$('override-'+i).value===''?null:$('override-'+i).valueAsNumber}))}}
function writeConfig(c){sim.validate(c,catalog);$('recovery').value=c.recovery;for(let i=0;i<2;i++){const a=c.actors[i];$('name-'+i).value=a.name||'무명';$('hp-'+i).value=a.max_hp;for(const k of keys)$(k+'-'+i).value=a.stats[k];$('weapon-'+i).value=a.weapon;$('policy-'+i).value=a.policy;for(let n=0;n<4;n++)$(`skill-${i}-${n}`).value=a.skills[n]||'';$('x-'+i).value=a.pos[0];$('y-'+i).value=a.pos[1];$('override-'+i).value=a.speed_override??''}summaries()}
function patternText(id){const s=sim.spatial(id,catalog.arts);return ({self:'자신',adjacent:'상하좌우 인접1칸',fan:'전방3칸',surround:'주변8칸',line2:'직선1~2칸'}[s.shape])+(s.pre?' · 전진 최대1칸':'')+(s.retreat?' · 후퇴1칸':'')+(s.push?' · 밀치기'+s.push+'칸':'')+(s.follow?' · 추격':'')}
function summaries(){const c=readConfig();for(let i=0;i<2;i++){const a=c.actors[i],total=keys.reduce((n,k)=>n+(Number.isFinite(a.stats[k])?a.stats[k]:0),0),speed=a.speed_override??10+a.stats.agility;$('summary-'+i).textContent=`합계 ${total} · 행동 속도 ${Number.isFinite(speed)?speed:'—'}${a.speed_override!=null?'(강제값)':''} · 시작 내기 ${Number.isFinite(a.stats.inner)?a.stats.inner:'—'}`;const lines=[];for(const id of [...new Set(a.skills)].filter(Boolean)){const s=catalog.arts[id],move=sim.action(id,a.stats,a.weapon,catalog),requirement=s.required_weapon_type==null?'무기 무관':({none:'맨손',sword:'검',saber:'도',spear:'창'}[s.required_weapon_type])+' 필요';lines.push(`<div class="${move?'':'bad'}"><strong>${escapeHtml(s.name)}</strong> · ${escapeHtml(patternText(id))}<br>${move?`방어 전 위력 ${Number.isFinite(move.raw)?Math.round(move.raw*100)/100:'—'} · 내기 ${move.cost}`:'장착 무기 불일치 · 사용하지 않음'} · ${escapeHtml(requirement)}</div>`)}$('info-'+i).innerHTML=lines.join('')||'선택한 무공이 없으면 기본공격을 사용합니다.'}}
function stop(){clearInterval(timer);timer=null;$('play').textContent='재생'}
function markDirty(){stop();dirty=true;$('dirty').textContent='설정 변경됨 · 다시 계산을 눌러 반영하세요.';summaries()}
function calculate(config=readConfig(),save=true){stop();try{sim.validate(config,catalog);const result=sim.run(config,catalog);lastConfig=JSON.parse(JSON.stringify(config));current=result;frame=0;dirty=false;$('errors').textContent='';$('dirty').textContent='입력한 설정으로 계산 완료';if(save)try{localStorage.setItem(STORAGE,JSON.stringify({schema:1,config:lastConfig}))}catch{};$('scrub').max=current.frames.length-1;buildResult();summaries();render();return true}catch(error){$('errors').textContent=error.message;$('dirty').textContent='입력 오류 · 이전 결과는 유지됩니다.';return false}}
function loadPreset(index){const c=data.cases[index];if(!c)return;writeConfig(sim.fromFixture(c,data));$('preset').value=String(index);calculate();}
function buildResult(){const c=current.config,actors=c.actors;$('warning').textContent=`새 계산 · ${actors[0].name} 대 ${actors[1].name} · ${c.recovery==='clock'?'공통 박자':'자기 행동'}마다 내기 회복. 실제 게임/NPC 수치는 바뀌지 않습니다.`;$('build').innerHTML=`<table><tr><th></th><th>${escapeHtml(actors[0].name)}</th><th>${escapeHtml(actors[1].name)}</th></tr>${keys.map((k,i)=>`<tr><td>${names[i]}</td><td>${actors[0].stats[k]}</td><td>${actors[1].stats[k]}</td></tr>`).join('')}</table><p>${actors.map(a=>`${escapeHtml(a.name)}: 체력${a.max_hp} · ${escapeHtml(catalog.weapons[a.weapon].name)}`).join('<br>')}</p><p>${current.draw?'200행동 상한 · 미결':escapeHtml(actors[current.winner].name)+' 승리'} · ${current.beats}박자<br>행동권 ${current.player_actions}:${current.enemy_actions} · 실제 공격 ${current.player_attacks}:${current.enemy_attacks}<br>종료 체력 ${current.summary.map(a=>a.hp).join(' : ')}</p><p class="muted">무공 선택/이동은 자동 판단입니다. 추가 이동·밀치기·방어/운기는 로그에 따로 표시합니다.</p>`;$('timeline').replaceChildren();current.frames.forEach((f,i)=>{let b=document.createElement('button');b.className=f.kind==='recovery'?'recovery':'';let t=document.createElement('span');t.className='time';t.textContent=f.beat.toFixed(2);b.append(t,document.createTextNode((f.actor>=0?actors[f.actor].name+' · ':'')+f.action+(f.damage?' −'+f.damage:'')+(f.restored?' · 내기+'+f.restored:'')));b.onclick=()=>{stop();frame=i;render()};$('timeline').append(b)})}
function actorCard(a,i){const original=current.config.actors[i],speed=original.speed_override??10+original.stats.agility;return `<h2>${escapeHtml(a.name)} <small>기민${original.stats.agility} · 속도${speed}${original.speed_override!=null?'(강제)':''}</small></h2><div class="nums">체력 ${a.hp} / ${a.max_hp}</div><div class="health"><span style="width:${a.hp/a.max_hp*100}%"></span></div><div class="nums">내기 ${a.qi} / 500 · 행동 게이지 ${a.gauge.toFixed(0)}</div><div class="health gauge"><span style="width:${Math.min(100,a.gauge)}%"></span></div>`}
function render(){if(!current)return;const f=current.frames[frame];$('player').innerHTML=actorCard(f.state[0],0);$('enemy').innerHTML=actorCard(f.state[1],1);$('board').replaceChildren();for(let y=1;y<=5;y++)for(let x=1;x<=7;x++){const cell=document.createElement('div');cell.className='cell';const co=document.createElement('span');co.className='coord';co.textContent=x+','+y;cell.append(co);if(f.path.some(p=>p[0]===x&&p[1]===y))cell.classList.add('path');f.state.forEach((a,i)=>{if(a.pos[0]!==x||a.pos[1]!==y)return;const token=document.createElement('span');token.className='token'+(i===1?' enemy':'')+(f.actor===i?' active':'')+(a.hp===0?' dead':'');token.textContent=a.name.length>4?a.name.slice(0,4)+'…':a.name;token.title=a.name;token.style.fontSize=a.name.length>4?'10px':'13px';cell.append(token);if(f.damage&&f.actor!==i){cell.classList.add('hit');const hit=document.createElement('span');hit.className='damage';hit.textContent='−'+f.damage;cell.append(hit)}});$('board').append(cell)}$('scrub').value=frame;$('counter').textContent=`${frame+1} / ${current.frames.length}`;$('previous').disabled=frame===0;$('next').disabled=frame===current.frames.length-1;let desc=f.kind==='start'?'행동 게이지0에서 시작합니다.':f.kind==='recovery'?f.action:`${current.config.actors[f.actor].name} · ${f.action}${f.basePath?.length?' · 기본 이동'+f.basePath.length+'칸':''}${f.skillPath?.length?' · 무공 이동'+f.skillPath.length+'칸':''}${f.pushed?.length?' · 밀치기'+f.pushed.length+'칸':''}${f.damage?' · 피해'+f.damage:''}${f.cost?' · 내기'+f.cost+' 소모':''}${f.restored?' · 내기'+f.restored+' 회복':''}`;if(frame===current.frames.length-1)desc+=' · '+(current.draw?'행동 상한 도달':'전투 종료');$('status').textContent=`${f.beat.toFixed(2)}박자 — ${desc}`;[...$('timeline').children].forEach((b,i)=>b.classList.toggle('current',i===frame));if(frame===current.frames.length-1)stop()}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
createEditors();const groups=new Map();data.cases.forEach((c,i)=>{const group=c.hp_scale===1?'기존 실제 정괴 비교':'기존 체력×4 검증';if(!groups.has(group)){const g=document.createElement('optgroup');g.label=group;groups.set(group,g);$('preset').append(g)}const o=document.createElement('option');o.value=i;o.textContent=`${c.control?'기민형·속도 고정':c.profile==='agility'?'기민형':'근력형'} · ${c.layout.title}${c.recovery==='per_action'?' · 행동별 회복':''}`;groups.get(group).append(o)});
$('settings').addEventListener('input',markDirty);$('settings').addEventListener('change',markDirty);$('calculate').onclick=()=>calculate();$('preset').onchange=()=>loadPreset(+$('preset').value);$('default').onclick=()=>loadPreset(0);$('stress').onclick=()=>loadPreset(15);$('export-config').onclick=()=>{try{const c=readConfig();sim.validate(c,catalog);download({schema:1,config:c},'murim-grid-config.json')}catch(e){$('errors').textContent=e.message}};$('import-config').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('설정 파일은100KB 이하로 선택하세요.');const value=JSON.parse(await file.text());if(value.schema!==1)throw Error('지원하지 않는 설정 형식입니다.');sim.validate(value.config,catalog);writeConfig(value.config);calculate()}catch(error){$('errors').textContent='설정 불러오기 실패: '+error.message}finally{e.target.value=''}};$('download-result').onclick=()=>download({schema:1,result:current},'murim-grid-result.json');
$('previous').onclick=()=>{stop();frame=Math.max(0,frame-1);render()};$('next').onclick=()=>{stop();frame=Math.min(current.frames.length-1,frame+1);render()};$('scrub').oninput=()=>{stop();frame=+$('scrub').value;render()};$('play').onclick=()=>{if(timer){stop();return}if(frame===current.frames.length-1)frame=0;timer=setInterval(()=>{frame++;render()},900);$('play').textContent='일시정지';render()};
const params=new URLSearchParams(location.search);let initialIndex=params.get('stress')==='1'?15:Number(params.get('preset'))||0;if(!Number.isInteger(initialIndex)||initialIndex<0||initialIndex>=data.cases.length)initialIndex=0;let initial=sim.fromFixture(data.cases[initialIndex],data);$('preset').value=String(initialIndex);if(!params.has('preset')&&!params.has('stress'))try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved?.schema===1){sim.validate(saved.config,catalog);initial=saved.config}}catch{}writeConfig(initial);calculate(initial,false);if(params.has('frame')){frame=Math.min(current.frames.length-1,Math.max(0,Number(params.get('frame'))||0));render()}document.body.dataset.ready='true';
// Test/review access to the same UI paths; never touches the actual game's saves.
window.simApp={loadPreset,calculate,readConfig,writeConfig,get result(){return current},showFrame(i){stop();frame=Math.max(0,Math.min(current.frames.length-1,i));render()}};
